"""Characterization tests generated by Inherit.

Each test pins behavior OBSERVED when the code ran; it records what the code does today,
not what it should do. Review tests marked REVIEW before treating them as correct.
Module state and the environment variables a call read are reset to what was recorded when
it was observed (monkeypatch restores them afterwards), so these tests neither depend on nor
leak into other tests' state.
"""
import copy

import pytest
import datekit.periods
import datekit.settings

# REVIEW: raises ValueError for these inputs; confirm this is intended
def test_datekit_periods_add_months_case_1():  # evidence: E-0035, E-0036
    with pytest.raises(ValueError) as info:
        datekit.periods.add_months(1, 1, 1, '')
    assert str(info.value) == "invalid literal for int() with base 10: ''"

# REVIEW: raises TypeError for these inputs; confirm this is intended
def test_datekit_periods_add_months_case_2():  # evidence: E-0035, E-0036
    with pytest.raises(TypeError) as info:
        datekit.periods.add_months(1, 1, 'a', 'abc')
    assert str(info.value) == "'str' object cannot be interpreted as an integer"

# REVIEW: raises TypeError for these inputs; confirm this is intended
